package android.graphics; public class Bitmap { public enum Config{ARGB_8888} private int w,h; private boolean recycled; private Bitmap(int x,int y){w=x;h=y;} public static Bitmap createBitmap(int w,int h,Config c){return new Bitmap(w,h);} public boolean isRecycled(){return recycled;} public void recycle(){recycled=true;} public boolean isMutable(){return true;} public void eraseColor(int c){} public int getWidth(){return w;} public int getHeight(){return h;} }